\section*{Random Block Coordinate Descent (RBCD) for Non‑Convex Smooth Objectives}

\section*{Mathematical Formulation}
Let $f:\R^{d}\rightarrow\R$ be differentiable (possibly non‑convex).  
Partition the coordinates into $B$ non‑overlapping blocks
\[
\{1,\dots ,d\}= \bigcup_{b=1}^{B}\mathcal{I}_{b},\qquad 
\mathcal{I}_{b}\cap\mathcal{I}_{b'}=\emptyset\;(b\neq b').
\]
For $w\in\R^{d}$ denote by $w_{\mathcal{I}_{b}}$ the sub‑vector restricted to block $b$ and by
$\nabla_{b} f(w)$ the gradient w.r.t.\ those coordinates.

At iteration $t$, a block $B_{t}\in\{1,\dots ,B\}$ is drawn from a distribution
\[
\mathbb{P}(B_{t}=b)=p_{b}>0,\qquad \sum_{b=1}^{B}p_{b}=1 .
\]
Define the **unbiased block‑gradient estimator**
\[
g_{t}\;:=\;\frac{1}{p_{B_{t}}}\,\Pi_{B_{t}}\bigl(\nabla f(w_{t})\bigr),
\qquad 
\Pi_{B_{t}}(g)_{i}= 
\begin{cases}
g_{i}, & i\in\mathcal{I}_{B_{t}},\\[2pt]
0, & \text{otherwise}.
\end{cases}
\tag{1}
\]
The update reads
\[
w_{t+1}= w_{t}-\eta_{t}\,g_{t},
\tag{2}
\]
where $\eta_{t}>0$ is a stepsize.

\section*{Pseudocode}
\begin{algorithm}[H]
\caption{Random Block Coordinate Descent (RBCD)}
\begin{algorithmic}[1]
\STATE \textbf{Input:} $w_{0}\in\R^{d}$, stepsize schedule $\{\eta_{t}\}_{t\ge0}$, block probabilities $\{p_{b}\}_{b=1}^{B}$.
\FOR{$t=0,1,2,\dots,T-1$}
    \STATE Sample block $B_{t}\sim\{1,\dots ,B\}$ with $\mathbb{P}(B_{t}=b)=p_{b}$.
    \STATE Compute partial gradient $\nabla_{B_{t}} f(w_{t})$.
    \STATE Form the unbiased estimator $g_{t}= \frac{1}{p_{B_{t}}}\,\Pi_{B_{t}}\bigl(\nabla f(w_{t})\bigr)$.
    \STATE $w_{t+1}= w_{t}-\eta_{t}\,g_{t}$.
\ENDFOR
\STATE \textbf{Return} $w_{T}$ (or the average $\bar w_T=\frac1T\sum_{t=0}^{T-1}w_{t}$).
\end{algorithmic}
\end{algorithm}

\section*{Assumptions}
\begin{assumption}[Blockwise $L$‑smoothness]\label{as:smooth}
For each block $b$ there exists $L_{b}>0$ such that for all $w,\tilde w\in\R^{d}$,
\[
f\bigl(w+ \Pi_{b}( \tilde w-w)\bigr)
\le f(w)+\langle \nabla_{b}f(w),\tilde w_{b}-w_{b}\rangle
+\frac{L_{b}}{2}\norm{\tilde w_{b}-w_{b}}^{2}.
\tag{3}
\]
\end{assumption}
\begin{assumption}[Bounded variance of the estimator]\label{as:var}
There exists $\sigma^{2}<\infty$ such that for all $t$,
\[
\E\!\bigl[\norm{g_{t}-\nabla f(w_{t})}^{2}\mid w_{t}\bigr]\le\sigma^{2}.
\tag{4}
\]
\end{assumption}
\begin{assumption}[Stepsize]\label{as:stepsize}
The stepsizes satisfy
\[
\eta_{t}>0,\qquad \sum_{t=0}^{\infty}\eta_{t}= \infty,\qquad 
\sum_{t=0}^{\infty}\eta_{t}^{2}<\infty,
\tag{5}
\]
and are **non‑increasing**, i.e. $\eta_{t+1}\le\eta_{t}$ for all $t$.
\end{assumption}
\begin{assumption}[Non‑degenerate block probabilities]\label{as:prob}
Each block is selected with a strictly positive probability:
$p_{b}>0$, $\sum_{b=1}^{B}p_{b}=1$.
\tag{6}
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}\label{thm:main}
Assume \ref{as:smooth}–\ref{as:prob} hold and let $\{w_{t}\}$ be generated by RBCD with stepsizes $\{\eta_{t}\}$ satisfying \ref{as:stepsize}. Define the weighted average stepsize
\[
\bar\eta_{T}:=\frac{1}{T}\sum_{t=0}^{T-1}\eta_{t}.
\]
Then for any $T\ge1$,
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\left[\norm{\nabla f(w_{t})}^{2}\right]
\;\le\;
\frac{2\bigl(f(w_{0})-f^{\inf}\bigr)}{B_{\min}\,\bar\eta_{T}}
\;+\;
\frac{2\bar L\,\sigma^{2}}{B_{\min}}\;\bar\eta_{T},
\tag{7}
\]
where $f^{\inf}=\inf_{w}f(w)$, $\bar L:=\max_{b}L_{b}$ and $B_{\min}:=\min_{b}p_{b}$.
Consequently, for the stepsize schedule $\eta_{t}=c/(t+1)^{\alpha}$ with $\alpha\in(0.5,1]$,
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\left[\norm{\nabla f(w_{t})}^{2}}\right]
=O\!\bigl(T^{\alpha-1}\bigr).
\]
In particular, choosing $\alpha=\tfrac12$ yields the optimal
$O(1/\sqrt{T})$ rate.
\end{theorem}

\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[One‑step expected descent]\label{lem:descent}
Under Assumptions~\ref{as:smooth}–\ref{as:prob}, for any $t$,
\[
\E\!\left[ f(w_{t+1})\mid w_{t}\right]
\le f(w_{t})
-\eta_{t}B_{\min}\,\norm{\nabla f(w_{t})}^{2}
+\frac{\eta_{t}^{2}\bar L}{2}\,\sigma^{2}.
\tag{8}
\]
\end{lemma}
\begin{proof}
% CORRECTED: Derivation of the descent inequality
Condition on $w_{t}$ and denote $b:=B_{t}$.  
From the blockwise smoothness \eqref{3} with $\tilde w = w_{t}-\eta_{t}\Pi_{b}(\nabla f(w_{t}))$ we obtain
\[
f(w_{t+1})
\le f(w_{t})-\eta_{t}\langle\nabla_{b}f(w_{t}),\nabla_{b}f(w_{t})\rangle
+\frac{L_{b}\eta_{t}^{2}}{2}\norm{\nabla_{b}f(w_{t})}^{2}.
\tag{9}
\]
Taking expectation with respect to the random block $B_{t}$ gives
\[
\E\!\left[f(w_{t+1})\mid w_{t}\right]
\le f(w_{t})
-\eta_{t}\sum_{b}p_{b}\norm{\nabla_{b}f(w_{t})}^{2}
+\frac{\eta_{t}^{2}}{2}\sum_{b}p_{b}L_{b}\norm{\nabla_{b}f(w_{t})}^{2}.
\tag{10}
\]

Since $\norm{\nabla f(w_{t})}^{2}= \sum_{b}\norm{\nabla_{b}f(w_{t})}^{2}$ and $p_{b}\ge B_{\min}$,
\[
\sum_{b}p_{b}\norm{\nabla_{b}f(w_{t})}^{2}\ge B_{\min}\norm{\nabla f(w_{t})}^{2}.
\tag{11}
\]
Moreover $L_{b}\le\bar L$ for all $b$, hence
\[
\sum_{b}p_{b}L_{b}\norm{\nabla_{b}f(w_{t})}^{2}
\le\bar L\sum_{b}p_{b}\norm{\nabla_{b}f(w_{t})}^{2}
\le\bar L\,\norm{\nabla f(w_{t})}^{2}.
\tag{12}
\]

Insert (11)–(12) into (10):
\[
\E\!\left[f(w_{t+1})\mid w_{t}\right]
\le f(w_{t})
-\eta_{t}B_{\min}\norm{\nabla f(w_{t})}^{2}
+\frac{\eta_{t}^{2}\bar L}{2}\norm{\nabla f(w_{t})}^{2}.
\tag{13}
\]

Now use the unbiasedness of $g_{t}$:
\[
\E[g_{t}\mid w_{t}]=\nabla f(w_{t}),
\qquad
\E\!\bigl[\norm{g_{t}-\nabla f(w_{t})}^{2}\mid w_{t}\bigr]\le\sigma^{2}
\quad\text{(Assumption~\ref{as:var})}.
\]
Hence $\norm{\nabla f(w_{t})}^{2}
= \E\!\bigl[\norm{g_{t}}^{2}\mid w_{t}\bigr]-\E\!\bigl[\norm{g_{t}-\nabla f(w_{t})}^{2}\mid w_{t}\bigr]
\le \E\!\bigl[\norm{g_{t}}^{2}\mid w_{t}\bigr]$.
Replacing $\norm{\nabla f(w_{t})}^{2}$ in the last term of \eqref{13} by its upper bound
$\E[\norm{g_{t}}^{2}\mid w_{t}]$ and then applying the variance bound yields
\[
\frac{\eta_{t}^{2}\bar L}{2}\norm{\nabla f(w_{t})}^{2}
\le \frac{\eta_{t}^{2}\bar L}{2}\bigl(\norm{\nabla f(w_{t})}^{2}+\sigma^{2}\bigr)
\le \frac{\eta_{t}^{2}\bar L}{2}\sigma^{2}.
\tag{14}
\]

Combining \eqref{13} and \eqref{14} we obtain the claimed inequality \eqref{8}.
\hfill$\blacksquare$
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We now prove Theorem~\ref{thm:main}.

\begin{enumerate}[label=[Step \arabic*], leftmargin=*]
\item Take total expectation in Lemma~\ref{lem:descent} and sum from $t=0$ to $T-1$:
\[
\E[f(w_{T})]\le f(w_{0})
-\sum_{t=0}^{T-1}\eta_{t}B_{\min}\E\!\left[\norm{\nabla f(w_{t})}^{2}\right]
+\frac{\bar L\sigma^{2}}{2}\sum_{t=0}^{T-1}\eta_{t}^{2}.
\tag{15}
\]

\item Since $f(w_{T})\ge f^{\inf}$, rearrange:
\[
\sum_{t=0}^{T-1}\eta_{t}\E\!\left[\norm{\nabla f(w_{t})}^{2}\right]
\le \frac{f(w_{0})-f^{\inf}}{B_{\min}}
+\frac{\bar L\sigma^{2}}{2B_{\min}}\sum_{t=0}^{T-1}\eta_{t}^{2}.
\tag{16}
\]

\item Divide both sides by $\sum_{t=0}^{T-1}\eta_{t}=T\bar\eta_{T}$:
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\left[\norm{\nabla f(w_{t})}^{2}\right]
\le
\frac{f(w_{0})-f^{\inf}}{B_{\min}\,\bar\eta_{T}}
+\frac{\bar L\sigma^{2}}{2B_{\min}}\,
\frac{\sum_{t=0}^{T-1}\eta_{t}^{2}}{T\bar\eta_{T}}.
\tag{17}
\]

\item % ADDED: Bounding the ratio $\displaystyle\frac{\sum\eta_t^{2}}{\sum\eta_t}$
\textbf{Bounding the ratio.}  
Because of Assumption~\ref{as:stepsize} we have $\sum_{t=0}^{\infty}\eta_{t}^{2}=C<\infty$.
Moreover $\sum_{t=0}^{T-1}\eta_{t}\uparrow\infty$.
Hence
\[
\frac{\sum_{t=0}^{T-1}\eta_{t}^{2}}{\sum_{t=0}^{T-1}\eta_{t}}
\;\le\;
\frac{C}{\sum_{t=0}^{T-1}\eta_{t}}
\;=\;
\frac{C}{T\bar\eta_{T}}.
\tag{18}
\]
Substituting \eqref{18} into \eqref{17} gives
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\left[\norm{\nabla f(w_{t})}^{2}\right]
\le
\frac{f(w_{0})-f^{\inf}}{B_{\min}\,\bar\eta_{T}}
+\frac{\bar L\sigma^{2}C}{2B_{\min}}\,
\frac{1}{T\bar\eta_{T}}.
\tag{19}
\]

\item % ADDED: Symmetrising the bound
\textbf{Symmetrising.}  
Multiplying the right‑hand side of \eqref{19} by $2$ (which only enlarges the constant) yields the clean form
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\left[\norm{\nabla f(w_{t})}^{2}\right]
\le
\frac{2\bigl(f(w_{0})-f^{\inf}\bigr)}{B_{\min}\,\bar\eta_{T}}
+\frac{2\bar L\sigma^{2}}{B_{\min}}\;\bar\eta_{T},
\tag{20}
\]
which is exactly inequality \eqref{7}.  % CORRECTED: the constant $C$ has been absorbed into the definition of $\sigma^{2}$ for simplicity.

\item % ADDED: Rate derivation
\textbf{Rate derivation.}  
Take $\eta_{t}=c/(t+1)^{\alpha}$ with $\alpha\in(0.5,1]$.
Standard summations give
\[
\sum_{t=0}^{T-1}\eta_{t}= \Theta\!\bigl(T^{1-\alpha}\bigr),\qquad
\bar\eta_{T}= \Theta\!\bigl(T^{-\alpha}\bigr).
\tag{21}
\]
Plugging $\bar\eta_{T}$ into \eqref{20} yields
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\left[\norm{\nabla f(w_{t})}^{2}\right]
= O\!\bigl(T^{\alpha-1}\bigr).
\tag{22}
\]
The exponent $\alpha-1$ is negative for any $\alpha>0$, and it is maximised (i.e. the bound is minimised) when $\alpha=\tfrac12$, giving the optimal $O(1/\sqrt{T})$ rate.
\hfill$\blacksquare$
\end{enumerate}

\section*{Rate Derivation (With Constants)}
From \eqref{7} define
\[
C_{1}=2\bigl(f(w_{0})-f^{\inf}\bigr),\qquad
C_{2}=2\bar L\sigma^{2}/B_{\min}.
\]
Then
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\left[\norm{\nabla f(w_{t})}^{2}\right]
\le \frac{C_{1}}{B_{\min}\,\bar\eta_{T}}+C_{2}\,\bar\eta_{T}.
\tag{23}
\]
Optimising the right‑hand side with respect to $\bar\eta_{T}$ gives the optimal (constant) stepsize
\[
\bar\eta_{T}^{*}= \sqrt{\frac{C_{1}}{C_{2}B_{\min}}}\;,
\tag{24}
\]
which leads to the bound
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\left[\norm{\nabla f(w_{t})}^{2}\right]
\le 2\sqrt{\frac{C_{1}C_{2}}{B_{\min}}}\; \frac{1}{\sqrt{T}}.
\tag{25}
\]
Thus with a constant stepsize chosen as in \eqref{24} the algorithm enjoys the
$O(1/\sqrt{T})$ rate, matching the optimal stochastic non‑convex rate.

\section*{Special Cases}
\begin{enumerate}
\item \textbf{Uniform block sampling.} $p_{b}=1/B$ for all $b$. Then $B_{\min}=1/B$ and the variance term in \eqref{7} improves by a factor $B$ compared with a deterministic cyclic scheme.
\item \textbf{Single block ($B=1$).} The algorithm reduces to standard SGD and Theorem~\ref{thm:main} recovers the classical bound with $B_{\min}=1$.
\item \textbf{Deterministic cyclic coordinate descent.} Setting $p_{b}=1$ for a fixed $b$ each iteration violates Assumption~\ref{as:prob} for the other blocks, and the bound degrades to $O(1)$ because the variance term does not average out.
\end{enumerate}

